#!/bin/bash
# Lines and bytes of the kt and ts sources by area; generated files (first line "Generated by") counted apart.
cd "$(dirname "$0")/../../ports" || exit 1
m() {  # m <ext> <gen|hand|all> <paths...>
  ext=$1; kind=$2; shift 2
  files=$(find "$@" -type f -name "*.$ext" 2>/dev/null)
  gen=$(echo "$files" | xargs grep -l -m1 '^// Generated by' 2>/dev/null)
  case $kind in
    gen)  files=$gen ;;
    hand) files=$(comm -23 <(echo "$files" | sort) <(echo "$gen" | sort)) ;;
  esac
  n=$(echo "$files" | grep -c .)
  s=$(echo "$files" | grep . | xargs cat 2>/dev/null | wc -lc | awk '{print $1" lines, "$2" bytes"}')
  echo "$n files, $s"
}
K=kt/src/commonMain/kotlin/plates
echo "kt core (hand):          $(m kt hand $K/core)"
echo "kt countries (hand):     $(m kt hand $K/countries)"
echo "kt countries (generated):$(m kt gen $K/countries)"
echo "kt holder/keypad/render/ui: $(m kt hand $K/holder $K/keypad $K/render $K/ui $K/Platform.kt)"
echo "kt jvmTest (hand):       $(m kt hand kt/src/jvmTest)"
echo "kt jvmTest (generated):  $(m kt gen kt/src/jvmTest)"
echo "ts core (hand):          $(m ts hand ts/src/core)"
echo "ts countries (hand):     $(m ts hand ts/src/countries)"
echo "ts countries (generated):$(m ts gen ts/src/countries)"
echo "ts holder/keypad/render/ui: $(m ts hand ts/src/holder ts/src/keypad ts/src/render ts/src/ui)"
echo "ts test (hand):          $(m ts hand ts/test)"
echo "ts test (generated):     $(m ts gen ts/test)"
